/* Baked tri-soup mesh from Human_Head_Particle_Me_Fracture3_Clean.obj (centered, scaled). Binary-packed for fast parse. */
function EE_B64F(s){var b=atob(s),n=b.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=b.charCodeAt(i);return new Float32Array(u.buffer);}
window.EE_HEAD_MESH = EE_B64F("");
